import math

def test_zero_score():
    assert solution.logistic_probability([0, 0], 0, [5, 7]) == 0.5

def test_lesson_example():
    p = solution.logistic_probability([1, -1], 0, [2, 0.5])
    assert abs(p - 0.8175744761936437) < 1e-12

def test_nonzero_bias():
    p = solution.logistic_probability([1], -2, [1])
    assert abs(p - 0.2689414213699951) < 1e-12

def test_symmetry():
    hi = solution.logistic_probability([1], 0, [3])
    lo = solution.logistic_probability([1], 0, [-3])
    assert abs(hi + lo - 1.0) < 1e-12

def test_large_negative():
    assert solution.logistic_probability([1], 0, [-1000]) == 0.0

def test_length_mismatch():
    try:
        solution.logistic_probability([1, 2], 0, [1])
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_returns_float():
